// AP Physics 1 review, Unit 6: Energy and Momentum of Rotating Systems (6.1 to 6.6). 42 multiple choice, one TBR and one EDA free-response question.
import { graph, bars } from "../../plot.js";
import { scene } from "../../diagrams.js";

const r = String.raw;
const pics = (word, svgs, title = "") => svgs.map((s, i) => ({ title: `${title}${title ? ", " : ""}${word} ${"ABCD"[i]}`, blocks: [{ svg: s }] }));
const one = (blocks, title = "") => [{ title, blocks }];

// ---- graphs, bar charts, and diagrams ----
// 6.1: energy bars of a rolling object, with the translational bar twice the rotational bar
const barsRoll = bars({ width: 360, height: 240, labels: ["Translational", "Rotational"], values: [8.0, 4.0], y: [0, 10], step: 2, yname: "Kinetic energy (J)",
  alt: "Bar chart of kinetic energy in joules for a rolling object. The translational bar is 8.0 joules and the rotational bar is 4.0 joules." });
// 6.1: angular speed of a rotor rises in a straight line from 0 to 40 rad/s in 8 s
const wRotor = graph({ width: 380, x: [0, 9], y: [0, 48], step: { x: 1, y: 8 }, xname: "t (s)", yname: "ω (rad/s)", segments: [[0, 0, 8, 40]],
  alt: "Angular speed versus time for a rotor. The graph is a straight line from 0 radians per second at 0 seconds to 40 radians per second at 8 seconds." });
// 6.2: a rope wound on a drum
const drum = scene({ width: 340, height: 210, alt: "A drum of radius 0.20 meters seen from the side, turning on a fixed axle at its center. A rope leaves the right side of the drum and hangs straight down, pulled by a 30 newton tension. A line from the center to the right edge is labeled r.",
  items: [{ circle: { x: 130, y: 110, r: 56 } }, { dot: { x: 130, y: 110, r: 3 } }, { line: { from: [130, 110], to: [186, 110] } }, { label: { x: 158, y: 122, text: "r" } },
    { rope: { points: [[186, 110], [186, 60]] } }, { arrow: { from: [186, 90], to: [186, 30], label: "T = 30 N", kind: "force", dx: 44 } }] });
// 6.2: torque versus angle, with a region of negative torque
const tauTheta = graph({ width: 400, x: [0, 9], y: [-8, 8], step: { x: 1, y: 2 }, xname: "θ (rad)", yname: "τ (N·m)", segments: [[0, 0, 2, 6], [2, 6, 4, 6], [4, 6, 8, -6]],
  alt: "Net torque on a disk versus angle. The torque rises in a straight line from 0 newton-meters at 0 radians to 6 newton-meters at 2 radians, stays at 6 newton-meters until 4 radians, then falls in a straight line, crossing 0 at 6 radians and reaching negative 6 newton-meters at 8 radians." });
// 6.3: torque versus time
const tauT = graph({ width: 400, x: [0, 9], y: [-4, 8], step: { x: 1, y: 2 }, xname: "t (s)", yname: "τ (N·m)", segments: [[0, 6, 3, 6], [3, 6, 3, -3], [3, -3, 5, -3], [5, -3, 5, 0], [5, 0, 8, 0]],
  alt: "Net torque on a wheel versus time. The torque is 6 newton-meters from 0 to 3 seconds, negative 3 newton-meters from 3 to 5 seconds, and 0 from 5 to 8 seconds." });
// 6.4: angular momentum of two disks before they stick together (opposite directions)
const barsL = bars({ width: 360, height: 240, labels: ["Disk A", "Disk B"], values: [6.0, -2.0], y: [-4, 8], step: 2, yname: "L (kg·m²/s)",
  alt: "Bar chart of the angular momentum of two disks before they stick together. Disk A has positive 6.0 kilogram-meters squared per second and disk B has negative 2.0." });
// 6.5: a solid cylinder on an incline; fric is the friction arrow of each picture, or none
const cylInc = ({ fric, tag, s = 150, h = false, alt }) => {
  const a = Math.PI / 6, c = Math.cos(a), sn = Math.sin(a), R = 24, x0 = 20, y0 = 24, L = 280;
  const cp = [x0 + s * c, y0 + s * sn], ctr = [cp[0] - R * sn, cp[1] + R * c];
  const items = [{ poly: { points: [[x0, y0], [x0 + L, y0], [x0 + L, y0 + L * Math.tan(a)]], fill: "none" } }, { ground: { from: [x0 + L, y0], to: [x0, y0] } },
    { circle: { x: ctr[0], y: ctr[1], r: R } }, { dot: { x: ctr[0], y: ctr[1], r: 2.5 } }, { line: { from: ctr, to: [ctr[0] + R * Math.cos(1.2), ctr[1] + R * Math.sin(1.2)] } },
    { arc: { x: x0, y: y0, r: 46, from: 0, to: 30, label: "θ" } }];
  if (tag) items.push({ label: { x: 36, y: 188, text: tag, anchor: "start" } });
  if (!h) items.push({ arrow: { from: ctr, to: [ctr[0] - 52 * c, ctr[1] - 52 * sn], kind: "velocity", label: "v", dy: 12 } });
  const f = { up: [c, sn], down: [-c, -sn], right: [1, 0] }[fric];
  if (f) items.push({ arrow: { from: cp, to: [cp[0] + 56 * f[0], cp[1] + 56 * f[1]], kind: "force", label: "f", dy: -8 } });
  if (fric === "none") items.push({ label: { x: cp[0] + 40, y: cp[1] - 22, text: "f = 0" } });
  if (h) {
    const yb = y0 + R * c;
    items.push({ line: { from: [x0, yb], to: [ctr[0] + 20, yb], dash: true } }, { line: { from: [ctr[0], ctr[1]], to: [ctr[0], yb], dash: true } }, { label: { x: ctr[0] - 10, y: (ctr[1] + yb) / 2, text: "h", anchor: "end" } });
  }
  return scene({ width: 330, height: 210, alt, items });
};
const fricPics = ["down", "right", "up", "none"].map((k, i) => cylInc({ fric: k, tag: "Diagram " + "ABCD"[i], alt: [
  "Diagram A: a cylinder on an incline rolling down the slope, with a friction force arrow at the contact point pointing down the slope.",
  "Diagram B: a cylinder on an incline rolling down the slope, with a friction force arrow at the contact point pointing horizontally to the right.",
  "Diagram C: a cylinder on an incline rolling down the slope, with a friction force arrow at the contact point pointing up the slope.",
  "Diagram D: a cylinder on an incline rolling down the slope, with no friction force, labeled f equals 0."][i] }));
const cylTop = cylInc({ fric: null, s: 230, h: true, alt: "A uniform solid cylinder sits near the top of an incline that makes an angle theta with the horizontal. A vertical dashed line labeled h shows the height of the cylinder's center above its position at the bottom of the incline." });
// 6.6: orbital speed versus radius, four candidate graphs (r in units of the planet's radius R, v in units of the speed at r = R)
const vr = (f, tag, alt, from = 1, to = 4) => graph({ width: 300, height: 220, x: [0, 5], y: [0, 2.5], step: { x: 1, y: 0.5 }, xname: "r / R", yname: "v / v₁", fns: [{ f, from, to }], labels: [[4.0, 2.3, tag]], alt });
const vrPics = [
  vr((x) => 1 / x, "Graph A", "Graph A: a curve that starts at 1 when r over R is 1 and falls steeply, reaching 0.25 at 4, bending toward the horizontal axis."),
  vr((x) => 1 / Math.sqrt(x), "Graph B", "Graph B: a curve that starts at 1 when r over R is 1 and falls gradually, reaching 0.5 at 4."),
  vr((x) => 1 - (x - 1) / 4, "Graph C", "Graph C: a straight line that starts at 1 when r over R is 1 and falls to 0.25 at 4."),
  vr((x) => Math.sqrt(x), "Graph D", "Graph D: a curve that starts at 1 when r over R is 1 and rises gradually, reaching 2 at 4."),
];
// 6.6: kinetic and potential energy bars of a satellite in a circular orbit
const barsOrbit = bars({ width: 360, height: 250, labels: ["Kinetic", "Potential"], values: [5.0, -10.0], y: [-12, 8], step: 4, yname: "Energy (MJ)",
  alt: "Bar chart of the energy of a satellite in a circular orbit, in megajoules. The kinetic energy bar is positive 5.0 and the gravitational potential energy bar is negative 10.0." });
// EDA: a block hanging from a string wound on the axle of a disk
const rig = scene({ width: 340, height: 230, alt: "A disk that turns on a fixed horizontal axle of radius 0.050 meters. A string is wound on the axle and hangs straight down from the right side to a block of mass m. A vertical arrow labeled h shows the height of the bottom of the block above the floor.",
  items: [{ circle: { x: 140, y: 175, r: 44 } }, { label: { x: 140, y: 205, text: "disk" } }, { circle: { x: 140, y: 175, r: 10 } }, { dot: { x: 140, y: 175, r: 2.5 } },
    { rope: { points: [[150, 175], [150, 90]] } }, { rect: { x: 150, y: 76, w: 34, h: 26, label: "m" } }, { line: { from: [150, 63], to: [220, 63], dash: true } },
    { arrow: { from: [212, 63], to: [212, 16], kind: "plain" } }, { label: { x: 224, y: 40, text: "h", anchor: "start" } }, { ground: { from: [20, 14], to: [300, 14] } }] });

export const sets = {
  "p6r-s01": { name: "A rolling object's energy", label: "Bar chart", intro: r`An object rolls without slipping along level ground. The bar chart shows its translational kinetic energy and its rotational kinetic energy at one instant.`, sources: one([{ svg: barsRoll }]) },
  "p6r-s02": { name: "A spinning rotor", label: "Graph", intro: r`A rotor has a rotational inertia of $0.020$ kg·m² about its axis. The graph shows its angular speed $\omega$ as a function of time.`, sources: one([{ svg: wRotor }]) },
  "p6r-s03": { name: "A rope on a drum", label: "Diagram", intro: r`A rope is wound around a drum of radius $0.20$ m that turns on a fixed axle through its center. The rope is pulled with a constant tension of $30$ N, directed along the rope as shown. The rope does not slip on the drum.`, sources: one([{ svg: drum }]) },
  "p6r-s04": { name: "A disk and a changing torque", label: "Graph", intro: r`A disk with a rotational inertia of $0.50$ kg·m² starts from rest on a frictionless axle. A net torque acts on it as shown, with the torque measured against the angle $\theta$ the disk has turned through since the start.`, sources: one([{ svg: tauTheta }]) },
  "p6r-s05": { name: "A grinding wheel", label: "Graph", intro: r`A grinding wheel with a rotational inertia of $1.5$ kg·m² starts from rest on a fixed axle. The graph shows the net torque on the wheel as a function of time, with counterclockwise torque positive.`, sources: one([{ svg: tauT }]) },
  "p6r-s06": { name: "A rotor test", label: "Data table", intro: r`A rotor starts from rest on a frictionless axle. A motor applies a constant net torque of $4.5$ N·m to it. The table shows the rotor's angular speed at several times.`,
    sources: one([{ table: { head: ["$t$ (s)", "$0$", "$2.0$", "$4.0$", "$6.0$"], rows: [["$\\omega$ (rad/s)", "$0$", "$3.0$", "$6.0$", "$9.0$"]] } }]) },
  "p6r-s07": { name: "Two disks that stick together", label: "Bar chart", intro: r`Disk A has a rotational inertia of $2.0$ kg·m² and disk B has a rotational inertia of $1.0$ kg·m². The disks sit on one frictionless vertical axle. Disk A spins counterclockwise and disk B spins clockwise, as seen from above. The bar chart shows their angular momenta about the axle, with counterclockwise positive. Disk B is then lowered onto disk A, and the two stick together and turn as one.`, sources: one([{ svg: barsL }]) },
  "p6r-s08": { name: "A cylinder rolling down a slope", label: "Diagrams", intro: r`A solid cylinder rolls without slipping down a rough incline. Four diagrams show the friction force $f$ that the incline exerts on the cylinder at its point of contact. Air resistance is negligible.`, sources: pics("Diagram", fricPics) },
  "p6r-s09": { name: "Speed of a satellite", label: "Graphs", intro: r`A satellite moves in a circular orbit of radius $r$ around a planet of radius $R$. Four graphs show the satellite's orbital speed $v$, in units of its speed $v_1$ in an orbit at $r = R$, as a function of the orbit's radius $r$, in units of $R$.`, sources: pics("Graph", vrPics) },
  "p6r-s10": { name: "Energy of a satellite", label: "Bar chart", intro: r`A satellite moves in a circular orbit around a planet. The bar chart shows its kinetic energy and its gravitational potential energy, with the potential energy zero at infinite separation.`, sources: one([{ svg: barsOrbit }]) },
  "p6r-s11": { name: "A cylinder rolling down an incline", label: "Free response", frq: "TBR",
    intro: r`A uniform solid cylinder of mass $m$ and radius $R$ is released from rest on a rough incline that makes an angle $\theta$ with the horizontal, as shown. The cylinder rolls without slipping to the bottom. The center of the cylinder starts a vertical height $h$ above its position at the bottom. The rotational inertia of the cylinder about its center is $\tfrac12 mR^2$. Express all algebraic answers in terms of $m$, $R$, $h$, $\theta$, and fundamental constants.`,
    sources: one([{ svg: cylTop }]) },
  "p6r-s12": { name: "A falling block and a disk", label: "Free response", frq: "EDA",
    intro: r`A student wants to determine the rotational inertia $I$ of a disk that turns on a fixed horizontal axle. A light string is wound around the axle, which has a radius $r = 0.050$ m, and a block of mass $m = 0.200$ kg hangs from the free end. When the block is released from rest, it falls and the string unwinds without slipping, turning the disk. Friction in the axle and air resistance are negligible. Use $g = 9.8$ m/s².`,
    sources: [{ title: "", blocks: [{ svg: rig }] }, { title: "Data", blocks: [{ p: r`In part (c), the student releases the block from five different heights $h$ and measures the speed $v$ just before it lands. The data are shown.` }, { table: { head: ["$h$ (m)", "$0.20$", "$0.40$", "$0.60$", "$0.80$", "$1.00$"], rows: [["$v$ (m/s)", "$0.75$", "$1.04$", "$1.30$", "$1.51$", "$1.66$"]] } }] }] },
};

// ---- multiple choice ----
const mc = (id, topic, difficulty, o) => ({ id: `p6r-${id}`, type: "mcq", skill: "u6", topic, difficulty, ...o, answer: 0 });
const mcq = [
  // 6.1 Rotational Kinetic Energy
  mc("m01", "6.1", "easy", { stem: r`A radar antenna turns about a fixed vertical axis through its center. Its rotational inertia about that axis is $40$ kg·m², and it turns at a constant angular speed of $3.0$ rad/s.`, question: "What is the antenna's rotational kinetic energy?",
    choices: [r`$180$ J`, r`$360$ J`, r`$120$ J`, r`$60$ J`],
    why: [r`$K = \tfrac12 I\omega^2 = \tfrac12(40)(3.0)^2 = 180$ J.`, r`This is $I\omega^2$, which leaves out the factor of one half.`, r`This is $I\omega$, the angular momentum in kg·m²/s, not an energy.`, r`This is $\tfrac12 I\omega$, which does not square the angular speed.`] }),
  mc("m02", "6.1", "easy", { stem: r`A solid cylinder of mass $M$ and radius $R$ rolls without slipping along level ground. Its center moves at speed $v$, and it turns at angular speed $\omega$ about its center. Its rotational inertia about its center is $I$.`, question: "Which statement describes the cylinder's total kinetic energy?",
    choices: [r`It is $\tfrac12 Mv^2$ for the center's motion plus $\tfrac12 I\omega^2$ for the turning.`, r`It is only $\tfrac12 Mv^2$, because the cylinder as a whole is moving along the ground.`, r`It is only $\tfrac12 I\omega^2$, because rolling is a turning motion of the whole cylinder.`, r`It is $\tfrac12 Mv^2 + \tfrac12 I\omega^2$ plus a second $\tfrac12 I\omega^2$ for the turning about the contact point.`],
    why: [r`The kinetic energy of a rigid body is the translational kinetic energy of its center of mass plus the rotational kinetic energy about the center of mass.`, r`This leaves out the energy of the turning, which is not zero when $\omega \neq 0$.`, r`This leaves out the energy of the center's motion, which is not zero when $v \neq 0$.`, r`This counts the turning twice. The motion about the contact point is already included in the sum of the first two terms.`] }),
  mc("m03", "6.1", "moderate", { set: "p6r-s02", question: r`By how much does the rotor's rotational kinetic energy increase between $t = 4.0$ s and $t = 8.0$ s?`,
    choices: [r`$12$ J`, r`$4.0$ J`, r`$16$ J`, r`$9.0$ J`],
    why: [r`From the graph, $\omega = 20$ rad/s at $4.0$ s and $40$ rad/s at $8.0$ s. $\Delta K = \tfrac12(0.020)(40^2 - 20^2) = 12$ J.`, r`This is $\tfrac12 I(\Delta\omega)^2$, which squares the change in angular speed instead of taking the difference of the squares.`, r`This is the kinetic energy at $8.0$ s, not the increase.`, r`This uses the average angular speed, $30$ rad/s, for the kinetic energy at $8.0$ s, $\tfrac12 I(30)^2$, and not the difference between the two energies.`] }),
  mc("m04", "6.1", "moderate", { stem: r`A solid sphere and a thin spherical shell have the same mass and the same radius $R$, and each spins about an axis through its center at the same angular speed. The rotational inertia is $\tfrac25 mR^2$ for the solid sphere and $\tfrac23 mR^2$ for the shell.`, question: "Which statement compares their rotational kinetic energies?",
    choices: [r`The shell has $\tfrac53$ as much.`, r`The solid sphere has $\tfrac53$ as much.`, r`They have equal energy, because the mass, radius, and angular speed are the same.`, r`The shell has $\tfrac{25}{9}$ as much.`],
    why: [r`$K = \tfrac12 I\omega^2$ with the same $\omega$, so the energies are in the ratio of the inertias: $\dfrac{2/3}{2/5} = \dfrac53$, with the shell larger.`, r`This inverts the ratio. The shell has the larger inertia, so it has the larger energy.`, r`The mass, radius, and angular speed are the same, but the mass is spread differently, so the inertias differ.`, r`This squares the ratio of the inertias, $(5/3)^2$. The energy is proportional to the inertia, not its square.`] }),
  mc("m05", "6.1", "moderate", { set: "p6r-s01", question: "Which object is rolling?",
    choices: [r`A solid cylinder`, r`A thin hoop`, r`A solid sphere`, r`A thin spherical shell`],
    why: [r`For rolling without slipping, $\dfrac{K_{rot}}{K_{trans}} = \dfrac{\tfrac12 I\omega^2}{\tfrac12 mv^2} = \dfrac{I}{mR^2}$. The bars give $4.0/8.0 = \tfrac12$, which is the solid cylinder's $I = \tfrac12 mR^2$.`, r`A hoop has $I = mR^2$, so its two bars would be equal.`, r`A solid sphere has $I = \tfrac25 mR^2$, so its rotational bar would be $\tfrac25$ of the translational bar, $3.2$ J here.`, r`A thin shell has $I = \tfrac23 mR^2$, so its rotational bar would be $\tfrac23$ of the translational bar, about $5.3$ J here.`] }),
  mc("m06", "6.1", "difficult", { stem: r`A thin hoop (rotational inertia $MR^2$) and a solid disk (rotational inertia $\tfrac12 MR^2$) have the same mass $M$ and the same radius $R$. Each rolls without slipping along level ground with its center moving at the same speed $v$.`, question: "What is the ratio of the hoop's total kinetic energy to the disk's total kinetic energy?",
    choices: [r`$\dfrac{4}{3}$`, r`$2$`, r`$1$`, r`$\dfrac{3}{4}$`],
    why: [r`With $\omega = v/R$, the hoop has $\tfrac12 Mv^2 + \tfrac12 Mv^2 = Mv^2$ and the disk has $\tfrac12 Mv^2 + \tfrac14 Mv^2 = \tfrac34 Mv^2$. The ratio is $\tfrac43$.`, r`This is the ratio of the rotational energies only, $\tfrac12 Mv^2 \big/ \tfrac14 Mv^2$.`, r`This is the ratio of the translational energies only. They have equal masses and equal speeds, but the rotational energies differ.`, r`This is the inverse of the correct ratio. The hoop has the larger total energy.`] }),
  // 6.2 Torque and Work
  mc("m07", "6.2", "easy", { stem: r`A mechanic turns a bolt with a torque wrench. The wrench exerts a constant torque of $60$ N·m on the bolt while the bolt turns through one quarter of a revolution.`, question: "How much work does the wrench do on the bolt?",
    choices: [r`$94$ J`, r`$15$ J`, r`$190$ J`, r`$5400$ J`],
    why: [r`$W = \tau\Delta\theta = (60)\left(\tfrac{\pi}{2}\right) = 94$ J, because a quarter turn is $\pi/2$ rad.`, r`This uses $\Delta\theta = 0.25$, the fraction of a revolution, instead of the angle in radians.`, r`This uses a half turn, $\Delta\theta = \pi$ rad.`, r`This uses the angle in degrees, $90$, instead of radians.`] }),
  mc("m08", "6.2", "easy", { stem: r`A turntable is spinning counterclockwise on a fixed axle. A brake then exerts a constant clockwise torque on the turntable while the turntable continues to turn counterclockwise through some angle.`, question: "What is true of the work done by the brake's torque during this angle?",
    choices: [r`It is negative, because the torque and the displacement are opposite.`, r`It is positive, because the torque is not zero and the turntable keeps turning through the angle.`, r`It is zero, because the axle does not move while the turntable turns on it.`, r`It is positive, because the brake makes the turntable slow down while it acts.`],
    why: [r`$W = \tau\Delta\theta$ is negative when the torque and the angular displacement have opposite signs. This removes kinetic energy from the turntable.`, r`The work depends on the signs of the torque and the displacement, not only on whether they are nonzero.`, r`The work done by a torque depends on the angle turned, not on the motion of the axle.`, r`The slowing is the effect of the negative work. The work itself is negative.`] }),
  mc("m09", "6.2", "moderate", { set: "p6r-s03", question: "The drum turns through $5.0$ revolutions. How much work does the rope do on the drum?",
    choices: [r`$190$ J`, r`$30$ J`, r`$940$ J`, r`$6.0$ J`],
    why: [r`The torque is $\tau = Tr = (30)(0.20) = 6.0$ N·m and the angle is $5.0 \times 2\pi = 31.4$ rad. $W = \tau\Delta\theta = 190$ J.`, r`This uses $\Delta\theta = 5.0$ for the number of revolutions instead of the angle in radians.`, r`This uses $T\Delta\theta$ with no lever arm, so it leaves out the radius $0.20$ m.`, r`This is the torque, $Tr$, in N·m. The work also needs the angle.`] }),
  mc("m10", "6.2", "moderate", { set: "p6r-s04", question: r`What is the disk's angular speed when it has turned through $\theta = 6.0$ rad?`,
    choices: [r`$9.8$ rad/s`, r`$12$ rad/s`, r`$8.5$ rad/s`, r`$6.9$ rad/s`],
    why: [r`The work is the area under the graph from $0$ to $6.0$ rad: $6 + 12 + 6 = 24$ J. Then $\tfrac12 I\omega^2 = 24$ gives $\omega = \sqrt{2(24)/0.50} = 9.8$ rad/s.`, r`This multiplies the largest torque, $6$ N·m, by the whole angle, which gives $36$ J.`, r`This uses only the area to $4.0$ rad, $18$ J, and stops counting when the torque starts to decrease.`, r`This sets $W = I\omega^2$ for $24$ J, which leaves out the factor of one half in the kinetic energy.`] }),
  mc("m11", "6.2", "moderate", { stem: r`A constant net torque acts on a flywheel that starts from rest. The flywheel reaches an angular speed of $20$ rad/s after $3.0$ revolutions. The same torque continues to act.`, question: "How many revolutions from the start has the flywheel turned through when its angular speed reaches $40$ rad/s?",
    choices: [r`$12$`, r`$6.0$`, r`$24$`, r`$9.0$`],
    why: [r`The work is $\tau\Delta\theta = \tfrac12 I\omega^2$, so $\Delta\theta \propto \omega^2$. Doubling $\omega$ makes the angle four times larger: $4 \times 3.0 = 12$ revolutions.`, r`This treats the angle as proportional to the angular speed.`, r`This doubles the angle a second time after finding that $\Delta\theta \propto \omega^2$.`, r`This is the additional revolutions after $20$ rad/s. The question asks for the total from the start.`] }),
  mc("m12", "6.2", "difficult", { set: "p6r-s04", question: r`What is the disk's angular speed when it has turned through $\theta = 8.0$ rad?`,
    choices: [r`$8.5$ rad/s`, r`$9.8$ rad/s`, r`$11$ rad/s`, r`$6.0$ rad/s`],
    why: [r`The area from $6.0$ to $8.0$ rad is negative, $-6$ J, so the net work is $24 - 6 = 18$ J. Then $\omega = \sqrt{2(18)/0.50} = 8.5$ rad/s.`, r`This stops at $6.0$ rad, where the torque is zero, and ignores the negative work after it.`, r`This adds the negative area as if it were positive, which gives $30$ J.`, r`This uses $\tfrac12 I\omega^2 = 18$ J with the factor of one half dropped, $\omega = \sqrt{W/I}$.`] }),
  // 6.3 Angular Momentum and Angular Impulse
  mc("m13", "6.3", "easy", { question: "Which of the following has the same units as angular momentum?",
    choices: [r`N·m·s`, r`N·m`, r`kg·m²/s²`, r`N·s`],
    why: [r`Angular momentum has units of kg·m²/s. Since N = kg·m/s², N·m·s = kg·m²/s.`, r`N·m is the unit of torque (and of energy), which is angular momentum divided by time.`, r`kg·m²/s² is the unit of energy, which is angular momentum divided by time again.`, r`N·s is the unit of linear impulse and momentum. Angular momentum also needs a length.`] }),
  mc("m14", "6.3", "easy", { stem: r`A constant net torque acts on a disk that starts at rest. After $3.0$ s the disk's angular speed is $\omega$.`, question: "What would the angular speed be after $6.0$ s of the same torque?",
    choices: [r`$2\omega$`, r`$4\omega$`, r`$\sqrt{2}\,\omega$`, r`$\omega$`],
    why: [r`The angular impulse $\tau\Delta t$ equals $I\Delta\omega$, so $\omega$ is proportional to $\Delta t$. Doubling the time doubles $\omega$.`, r`This applies the scaling of the kinetic energy, which is proportional to $\omega^2$, to the angular speed.`, r`This treats the angular speed as proportional to the square root of the time.`, r`The torque is still acting, so the angular momentum keeps increasing.`] }),
  mc("m15", "6.3", "moderate", { set: "p6r-s05", question: "What is the wheel's angular speed at $t = 5.0$ s?",
    choices: [r`$8.0$ rad/s`, r`$12$ rad/s`, r`$16$ rad/s`, r`$18$ rad/s`],
    why: [r`The angular impulse is the area under the graph: $(6)(3) - (3)(2) = 12$ kg·m²/s. Then $\omega = \Delta L/I = 12/1.5 = 8.0$ rad/s.`, r`This counts only the positive torque, $18/1.5$, and ignores the negative torque after $3.0$ s.`, r`This adds the two areas as if both were positive, $24/1.5$.`, r`This is the angular momentum at $3.0$ s, $18$ kg·m²/s, read as an angular speed.`] }),
  mc("m16", "6.3", "moderate", { set: "p6r-s05", question: "At which time is the wheel's angular speed greatest?",
    choices: [r`$3.0$ s, when the torque changes sign`, r`$5.0$ s, when the net torque becomes zero again`, r`$8.0$ s, because the torque has acted for the longest time`, r`$1.5$ s, halfway through the interval of greatest torque`],
    why: [r`The angular momentum increases while the torque is positive, until $3.0$ s. After that the torque is negative and the angular momentum decreases.`, r`The torque is negative from $3.0$ s to $5.0$ s, so the angular speed is falling, not rising, during that time.`, r`The torque is zero after $5.0$ s, so the angular speed stays constant, but at a smaller value than at $3.0$ s.`, r`The torque is $6$ N·m during the whole first $3.0$ s, so the angular speed keeps increasing past $1.5$ s.`] }),
  mc("m17", "6.3", "moderate", { set: "p6r-s06", question: "What is the rotor's rotational inertia?",
    choices: [r`$3.0$ kg·m²`, r`$0.50$ kg·m²`, r`$0.33$ kg·m²`, r`$27$ kg·m²`],
    why: [r`The angular impulse equals the change in angular momentum: $\tau\Delta t = I\Delta\omega$. At $t = 6.0$ s, $I = \dfrac{(4.5)(6.0)}{9.0} = 3.0$ kg·m².`, r`This is $\tau/\omega = 4.5/9.0$, which leaves the time out.`, r`This is $\omega/(\tau\Delta t)$, the inverse of the rotational inertia.`, r`This is the angular momentum, $\tau\Delta t = 27$ kg·m²/s, and does not divide by the angular speed.`] }),
  mc("m18", "6.3", "moderate", { stem: r`A pulsar is a neutron star that can be modeled as a uniform solid sphere of mass $2.8 \times 10^{30}$ kg and radius $1.2 \times 10^{4}$ m. It makes one rotation every $0.033$ s. The rotational inertia of a uniform solid sphere about its center is $\tfrac25 mR^2$.`, question: "What is the magnitude of the pulsar's angular momentum?",
    choices: [r`$3.1 \times 10^{40}$ kg·m²/s`, r`$7.7 \times 10^{39}$ kg·m²/s`, r`$4.9 \times 10^{39}$ kg·m²/s`, r`$5.1 \times 10^{40}$ kg·m²/s`],
    why: [r`$I = \tfrac25(2.8\times10^{30})(1.2\times10^4)^2 = 1.6\times10^{38}$ kg·m², $\omega = 2\pi/0.033 = 190$ rad/s, and $L = I\omega = 3.1\times10^{40}$ kg·m²/s.`, r`This uses $6.0 \times 10^3$ m, half the radius, in the rotational inertia.`, r`This uses $\omega = 1/T = 30$ rad/s and leaves out the factor of $2\pi$.`, r`This uses $I = \tfrac23 mR^2$, the formula for a thin shell, not a solid sphere.`] }),
  mc("m19", "6.3", "moderate", { stem: r`A bicycle wheel can be modeled as a thin hoop of mass $1.2$ kg and radius $0.33$ m. It spins at $15$ rad/s on a fixed axle. A brake pad presses on the rim and exerts a constant friction force along the rim that stops the wheel in $2.0$ s.`, question: "What is the magnitude of the friction force?",
    choices: [r`$3.0$ N`, r`$0.98$ N`, r`$9.0$ N`, r`$1.5$ N`],
    why: [r`$I = mR^2 = 0.131$ kg·m² and $L = I\omega = 1.96$ kg·m²/s. Then $\tau = L/\Delta t = 0.98$ N·m, and $f = \tau/R = 3.0$ N.`, r`This is the torque in N·m. The force is the torque divided by the lever arm $0.33$ m.`, r`This divides the torque by $R^2$ instead of $R$.`, r`This uses $I = \tfrac12 mR^2$, which is the formula for a disk, not a hoop.`] }),
  mc("m20", "6.3", "moderate", { stem: r`Two identical disks, A and B, start from rest on identical frictionless axles. A constant net torque $\tau$ acts on disk A for a time $3t$. A constant net torque $2\tau$ acts on disk B for a time $t$.`, question: "What is the ratio of disk A's final kinetic energy to disk B's final kinetic energy?",
    choices: [r`$\dfrac{9}{4}$`, r`$\dfrac{3}{2}$`, r`$\dfrac{2}{3}$`, r`$\dfrac{4}{9}$`],
    why: [r`The final angular momenta are $L_A = 3\tau t$ and $L_B = 2\tau t$. With equal inertias, $K = L^2/(2I)$, so $K_A/K_B = (3/2)^2 = 9/4$.`, r`This is the ratio of the angular momenta, $L_A/L_B$. The kinetic energy is proportional to $L^2$.`, r`This is the inverse of the ratio of the angular momenta.`, r`This is the inverse of the correct ratio of the kinetic energies.`] }),
  mc("m21", "6.3", "moderate", { stem: r`A $0.50$ kg ball moves at a constant velocity of $4.0$ m/s along a straight horizontal line. The line passes at a perpendicular distance of $3.0$ m from a fixed point $P$. At one instant the ball is $5.0$ m from $P$.`, question: "What is the magnitude of the ball's angular momentum about $P$?",
    choices: [r`$6.0$ kg·m²/s`, r`$10$ kg·m²/s`, r`$8.0$ kg·m²/s`, r`$0$`],
    why: [r`For a particle, $L = mv r_\perp$, where $r_\perp$ is the perpendicular distance from $P$ to the line of motion: $(0.50)(4.0)(3.0) = 6.0$ kg·m²/s.`, r`This uses the distance $5.0$ m from $P$ at that instant, which is not the perpendicular distance.`, r`This uses $4.0$ m, the distance along the line from the closest point to the ball, as the lever arm.`, r`The ball is not moving in a circle, but its velocity does not point at $P$, so its angular momentum about $P$ is not zero.`] }),
  mc("m22", "6.3", "difficult", { stem: r`A uniform disk of mass $m$ and radius $R$ starts from rest on a frictionless axle through its center. A constant force of magnitude $F$ acts tangentially at the rim for a time $t$. The rotational inertia of the disk is $\tfrac12 mR^2$.`, question: "What is the disk's angular speed at the end of this time?",
    choices: [r`$\dfrac{2Ft}{mR}$`, r`$\dfrac{Ft}{mR}$`, r`$\dfrac{2Ft}{mR^2}$`, r`$\dfrac{Ft}{2mR}$`],
    why: [r`The angular impulse is $(FR)t = I\omega = \tfrac12 mR^2\omega$, so $\omega = \dfrac{2Ft}{mR}$.`, r`This uses $I = mR^2$, which is the inertia of a hoop.`, r`This uses the force as the torque and leaves out the lever arm $R$.`, r`This puts the factor of one half in the wrong place, as if $I = 2mR^2$.`] }),
  mc("m23", "6.3", "difficult", { stem: r`Hoop A and hoop B have the same mass. The radius of hoop B is twice the radius of hoop A. Each hoop spins on a fixed axle through its center, and the rims of the two hoops move at the same speed. The same constant braking torque is applied to each hoop until it stops.`, question: "What is the ratio of the stopping time of hoop B to the stopping time of hoop A?",
    choices: [r`$2$`, r`$4$`, r`$1$`, r`$\dfrac{1}{2}$`],
    why: [r`For a hoop, $L = I\omega = mR^2(v/R) = mRv$. With the same $m$ and $v$, $L_B/L_A = 2$. The stopping time is $L/\tau$, so the ratio is $2$.`, r`This is the ratio if the two hoops had the same angular speed, so that $L \propto R^2$. The rim speeds are equal, so the angular speeds are not.`, r`This assumes that equal rim speeds and equal masses give equal angular momenta, but the lever arm is different.`, r`This inverts the ratio. The larger hoop has the larger angular momentum and takes longer to stop.`] }),
  // 6.4 Conservation of Angular Momentum
  mc("m24", "6.4", "easy", { stem: r`A diver leaves a board with some rotation and is in the air in a straight position. The diver then pulls into a tuck, with the arms and legs close to the body. Air resistance is negligible.`, question: "What happens to the diver's angular speed and angular momentum as the diver tucks?",
    choices: [r`The angular speed increases and the angular momentum stays the same.`, r`The angular speed and the angular momentum both increase, because the rotational inertia decreases.`, r`The angular speed stays the same and the angular momentum decreases, because the rotational inertia decreases.`, r`The angular speed decreases and the angular momentum stays the same, because the rotational inertia decreases.`],
    why: [r`The net external torque is zero, so $L$ is constant. Tucking decreases the rotational inertia $I$, so $\omega = L/I$ increases.`, r`The angular momentum cannot increase without a net external torque. Nothing exerts one on the diver in the air.`, r`The angular momentum is conserved, and the angular speed changes because the inertia changes.`, r`This reverses the effect. A smaller inertia with the same $L$ means a larger $\omega$.`] }),
  mc("m25", "6.4", "easy", { stem: r`A gymnast rotates in the air in a tuck, with a rotational inertia of $3.0$ kg·m² and an angular speed of $4.0$ rad/s. The gymnast then extends into a straight layout with a rotational inertia of $9.0$ kg·m². Air resistance is negligible.`, question: "What is the gymnast's angular speed in the layout?",
    choices: [r`$1.3$ rad/s`, r`$12$ rad/s`, r`$0.44$ rad/s`, r`$4.0$ rad/s`],
    why: [r`There is no net external torque, so $I_i\omega_i = I_f\omega_f$ and $\omega_f = (3.0)(4.0)/9.0 = 1.3$ rad/s.`, r`This multiplies the angular speed by the ratio $9.0/3.0$. The inertia increases, so the angular speed decreases.`, r`This multiplies by $(3.0/9.0)^2$, which is the factor for the inverse square of the ratio of the inertias.`, r`This assumes that the angular speed does not change. It is the angular momentum that is conserved.`] }),
  mc("m26", "6.4", "moderate", { set: "p6r-s07", question: "What is the angular speed of the combined disks after they stick together?",
    choices: [r`$1.3$ rad/s`, r`$2.7$ rad/s`, r`$2.0$ rad/s`, r`$4.0$ rad/s`],
    why: [r`The total angular momentum is conserved: $6.0 + (-2.0) = 4.0$ kg·m²/s. The combined inertia is $3.0$ kg·m², so $\omega = 4.0/3.0 = 1.3$ rad/s.`, r`This adds the magnitudes, $8.0/3.0$, and ignores that disk B turns the opposite way.`, r`This divides the total angular momentum by the inertia of disk A alone.`, r`This is the total angular momentum, $4.0$ kg·m²/s, read as an angular speed.`] }),
  mc("m27", "6.4", "moderate", { stem: r`A student sits at rest on a stool that turns on a frictionless vertical axle. The student holds a bicycle wheel above the head with its axle vertical. The wheel spins counterclockwise, as seen from above, with an angular momentum of $4.0$ kg·m²/s about the vertical axis. The student and stool have a rotational inertia of $2.0$ kg·m². The student flips the wheel over, so that it spins clockwise about the same vertical axis with the same angular momentum magnitude.`, question: "What is the angular speed of the student and stool afterward?",
    choices: [r`$4.0$ rad/s counterclockwise`, r`$2.0$ rad/s counterclockwise`, r`$0$`, r`$8.0$ rad/s counterclockwise`],
    why: [r`The total angular momentum of the wheel, student, and stool is conserved at $+4.0$ kg·m²/s. After the flip, $+4.0 = -4.0 + I\omega$, so $I\omega = 8.0$ and $\omega = 8.0/2.0 = 4.0$ rad/s counterclockwise.`, r`This divides only $4.0$ kg·m²/s by $I$, which counts the change in the wheel's angular momentum as $4.0$ instead of $8.0$.`, r`This assumes that the student stays at rest because the total angular momentum is conserved. The wheel's angular momentum changed, so the student's must change too.`, r`This is the change in the wheel's angular momentum, $8.0$ kg·m²/s, read as an angular speed.`] }),
  mc("m28", "6.4", "moderate", { stem: r`A playground platform is a uniform disk of mass $60$ kg and radius $2.0$ m that turns on a frictionless axle through its center. The platform's rotational inertia is $\tfrac12 MR^2$. A child of mass $30$ kg stands at the rim, and the platform and child rotate together at $1.2$ rad/s. The child walks to a point $1.0$ m from the center. Treat the child as a point mass.`, question: "What is the angular speed of the platform afterward?",
    choices: [r`$1.9$ rad/s`, r`$1.6$ rad/s`, r`$4.8$ rad/s`, r`$1.2$ rad/s`],
    why: [r`$I_i = \tfrac12(60)(2.0)^2 + 30(2.0)^2 = 240$ kg·m², and $I_f = 120 + 30(1.0)^2 = 150$ kg·m². Then $\omega_f = (240)(1.2)/150 = 1.9$ rad/s.`, r`This takes the child's inertia to vary with $r$ instead of $r^2$, which gives $I_f = 180$ kg·m².`, r`This uses the child's inertia alone, $120/30$ times $1.2$, and leaves out the platform's inertia.`, r`This assumes that the angular speed is unchanged. The angular momentum is conserved, not the angular speed.`] }),
  mc("m29", "6.4", "moderate", { stem: r`A thin uniform rod of mass $M$ and length $L$ spins about a fixed vertical axis through its center on a frictionless horizontal table, with angular speed $\omega_0$. The rotational inertia of the rod about its center is $\tfrac{1}{12}ML^2$. Two small lumps of clay, each of mass $m$, are dropped onto the rod, one at each end, and stick to it.`, question: "What is the angular speed of the rod and clay afterward?",
    choices: [r`$\dfrac{M\omega_0}{M + 6m}$`, r`$\omega_0\sqrt{\dfrac{M}{M + 6m}}$`, r`$\dfrac{2M\omega_0}{2M + 3m}$`, r`$\dfrac{M\omega_0}{M + 24m}$`],
    why: [r`$L$ is conserved: $\tfrac{1}{12}ML^2\omega_0 = \left(\tfrac{1}{12}ML^2 + 2m\left(\tfrac{L}{2}\right)^2\right)\omega$, so $\omega = \dfrac{M\omega_0}{M + 6m}$.`, r`This conserves kinetic energy instead of angular momentum. The clay sticks to the rod, so energy is not conserved.`, r`This uses $\tfrac13 ML^2$, the inertia of a rod about its end, for the rod's own inertia.`, r`This puts each lump a distance $L$ from the axis instead of $L/2$.`] }),
  mc("m30", "6.4", "difficult", { set: "p6r-s07", question: "How much kinetic energy is lost when the disks stick together?",
    choices: [r`$8.3$ J`, r`$11$ J`, r`$2.7$ J`, r`$6.3$ J`],
    why: [r`Using $K = L^2/(2I)$: $K_A = 36/4 = 9.0$ J and $K_B = 4/2 = 2.0$ J, so $K_i = 11$ J. After sticking, $K_f = 4^2/(2 \times 3.0) = 2.7$ J. The loss is $11 - 2.7 = 8.3$ J.`, r`This is the total initial kinetic energy. Some kinetic energy remains after the disks stick.`, r`This is the final kinetic energy, not the energy lost.`, r`This compares the final energy only with disk A's initial energy, $9.0 - 2.7$, and leaves out disk B's $2.0$ J.`] }),
  // 6.5 Rolling
  mc("m31", "6.5", "easy", { set: "p6r-s08", question: "Which diagram shows the friction force on the cylinder?",
    choices: [r`Diagram C`, r`Diagram A`, r`Diagram B`, r`Diagram D`],
    why: [r`The weight has a component down the slope, which would make the contact point slide down. Static friction acts up the slope, which is also what gives the cylinder its angular acceleration.`, r`Friction down the slope would increase the net force down the slope and would slow the cylinder's turning. It does not match rolling without slipping.`, r`Friction on the contact point must be along the surface of the incline, not horizontal.`, r`Without friction, the cylinder would slide down the slope without turning. A rolling cylinder needs a friction torque.`] }),
  mc("m32", "6.5", "moderate", { stem: r`A solid ball rolls without slipping at a constant speed along a level floor. Air resistance is negligible.`, question: "What is true of the friction force that the floor exerts on the ball?",
    choices: [r`It is zero, because the ball's speed is constant.`, r`It points forward, because friction must keep the ball turning as it rolls.`, r`It points backward, because the floor always opposes the motion of the ball.`, r`It points backward with magnitude $\mu_k F_N$, because the ball is in contact with the floor.`],
    why: [r`The ball's center moves at constant velocity, so the net force is zero. The only horizontal force is friction, so it is zero. The ball needs no torque to keep turning at a constant rate.`, r`A forward friction force would speed up the center, and the speed is constant.`, r`A backward friction force would slow the center, and the speed is constant.`, r`Kinetic friction applies only when the contact point slides, and for rolling without slipping there is no sliding.`] }),
  mc("m33", "6.5", "moderate", { stem: r`A bicycle moves along level ground at $6.0$ m/s. The tires roll without slipping.`, question: "What is the speed of the top of a tire relative to the ground?",
    choices: [r`$12$ m/s`, r`$6.0$ m/s`, r`$0$`, r`$8.5$ m/s`],
    why: [r`The top of the tire moves at $v_{cm}$ forward because of the bicycle's motion and at $\omega R = v_{cm}$ forward because of the turning, so its speed relative to the ground is $2v_{cm} = 12$ m/s.`, r`This is the speed of the center, which is the same as the bicycle's. The top moves faster than the center.`, r`This is the speed of the point of the tire that touches the ground. The top is at the opposite side of the wheel.`, r`This is $\sqrt{2}v_{cm}$, the speed of a point on the tire at the same height as the axle.`] }),
  mc("m34", "6.5", "moderate", { stem: r`A solid sphere rolls without slipping along a level floor at speed $v_0$ and then up a rough incline, continuing to roll without slipping. The rotational inertia of the sphere is $\tfrac25 mR^2$. The sphere stops momentarily at a height $h$ above the floor.`, question: "What is $h$?",
    choices: [r`$\dfrac{7v_0^2}{10g}$`, r`$\dfrac{v_0^2}{2g}$`, r`$\dfrac{7v_0^2}{5g}$`, r`$\dfrac{5v_0^2}{14g}$`],
    why: [r`The initial kinetic energy is $\tfrac12 mv_0^2 + \tfrac12\left(\tfrac25 mR^2\right)\left(\tfrac{v_0}{R}\right)^2 = \tfrac{7}{10}mv_0^2$. Setting this equal to $mgh$ gives $h = \dfrac{7v_0^2}{10g}$.`, r`This counts only the translational kinetic energy and ignores the rotational kinetic energy.`, r`This leaves the factor of one half out of the total kinetic energy, $\tfrac75 mv_0^2$.`, r`This divides the translational energy by the factor $\tfrac75$ instead of multiplying by $\tfrac75$.`] }),
  mc("m35", "6.5", "moderate", { stem: r`A solid disk and a thin hoop have the same mass and the same radius. They are released from rest at the same height on a rough incline and roll without slipping to the bottom. The rotational inertias are $\tfrac12 mR^2$ for the disk and $mR^2$ for the hoop.`, question: "What is the ratio of the disk's speed to the hoop's speed at the bottom?",
    choices: [r`$\dfrac{2}{\sqrt{3}}$`, r`$\dfrac{4}{3}$`, r`$\dfrac{\sqrt{3}}{2}$`, r`$1$`],
    why: [r`For rolling from rest through a drop $h$: $mgh = \tfrac12 mv^2\left(1 + \dfrac{I}{mR^2}\right)$. This gives $v_{disk} = \sqrt{4gh/3}$ and $v_{hoop} = \sqrt{gh}$, so the ratio is $2/\sqrt{3}$.`, r`This is the ratio of the squares of the speeds. The speed is the square root of that ratio.`, r`This is the inverse of the correct ratio. The disk has less rotational inertia and reaches the bottom faster.`, r`The masses and radii are equal, but the rotational inertias differ, so the shares of energy that go into the turning differ.`] }),
  mc("m36", "6.5", "difficult", { stem: r`A solid cylinder rolls without slipping down a rough incline that makes an angle $\theta$ with the horizontal. The rotational inertia of the cylinder is $\tfrac12 mR^2$.`, question: "What is the smallest coefficient of static friction between the cylinder and the incline that allows the cylinder to roll without slipping?",
    choices: [r`$\dfrac{1}{3}\tan\theta$`, r`$\tan\theta$`, r`$\dfrac{1}{2}\tan\theta$`, r`$\dfrac{2}{3}\tan\theta$`],
    why: [r`Newton's second law along the slope: $mg\sin\theta - f = ma$. The torque equation: $fR = \tfrac12 mR^2(a/R)$, so $f = \tfrac12 ma$. Then $a = \tfrac23 g\sin\theta$ and $f = \tfrac13 mg\sin\theta$. Requiring $f \le \mu mg\cos\theta$ gives $\mu \ge \tfrac13\tan\theta$.`, r`This is the condition for a block that slides at constant speed, where friction equals $mg\sin\theta$. The rolling cylinder needs only a part of that.`, r`This is the result for a thin hoop, where $f = \tfrac12 mg\sin\theta$.`, r`This uses the factor from the acceleration, $a = \tfrac23 g\sin\theta$, in place of the factor for the friction force.`] }),
  // 6.6 Motion of Orbiting Satellites
  mc("m37", "6.6", "easy", { set: "p6r-s10", question: "What is the total mechanical energy of the satellite?",
    choices: [r`$-5.0$ MJ`, r`$+5.0$ MJ`, r`$-10$ MJ`, r`$+15$ MJ`],
    why: [r`The total energy is $K + U = 5.0 + (-10) = -5.0$ MJ. The negative sign means that the satellite is bound to the planet.`, r`This is the kinetic energy alone, which leaves out the potential energy.`, r`This is the potential energy alone, which leaves out the kinetic energy.`, r`This subtracts the negative potential energy, $5.0 - (-10)$, instead of adding it.`] }),
  mc("m38", "6.6", "moderate", { stem: r`A satellite moves in a circular orbit of radius $1.0 \times 10^{7}$ m around Mars. The mass of Mars is $6.42 \times 10^{23}$ kg. Use $G = 6.67 \times 10^{-11}$ N·m²/kg².`, question: "What is the satellite's orbital speed?",
    choices: [r`$2.1 \times 10^{3}$ m/s`, r`$2.9 \times 10^{3}$ m/s`, r`$1.5 \times 10^{3}$ m/s`, r`$4.3 \times 10^{6}$ m/s`],
    why: [r`Gravity provides the centripetal force, $\dfrac{GMm}{r^2} = \dfrac{mv^2}{r}$, so $v = \sqrt{GM/r} = 2.1 \times 10^{3}$ m/s.`, r`This is the escape speed at that radius, $\sqrt{2GM/r}$.`, r`This puts a factor of $2r$ in the denominator, $\sqrt{GM/(2r)}$.`, r`This is $GM/r$ without the square root, which has units of m²/s².`] }),
  mc("m39", "6.6", "moderate", { set: "p6r-s09", question: "Which graph correctly shows the orbital speed as a function of the radius of the orbit?",
    choices: [r`Graph B`, r`Graph A`, r`Graph C`, r`Graph D`],
    why: [r`$v = \sqrt{GM/r}$, so $v \propto r^{-1/2}$. At $r = 4R$ the speed is $\tfrac12 v_1$, and the curve flattens as $r$ increases.`, r`This graph shows $v \propto 1/r$, where the speed at $4R$ would be $\tfrac14 v_1$.`, r`This graph shows a speed that decreases linearly, which does not match $v \propto r^{-1/2}$.`, r`This graph shows the speed increasing with $r$. A satellite in a larger orbit moves more slowly.`] }),
  mc("m40", "6.6", "moderate", { stem: r`Two satellites of equal mass move in circular orbits around the same planet. The radius of satellite B's orbit is four times the radius of satellite A's orbit.`, question: "What is the ratio of the magnitude of B's angular momentum about the planet's center to the magnitude of A's?",
    choices: [r`$2$`, r`$4$`, r`$\dfrac{1}{2}$`, r`$8$`],
    why: [r`$L = mvr$ with $v = \sqrt{GM/r}$ gives $L = m\sqrt{GMr}$, so $L \propto \sqrt{r}$. The ratio is $\sqrt{4} = 2$.`, r`This takes $L \propto r$, as if both satellites moved at the same speed.`, r`This is the ratio of the orbital speeds, $v_B/v_A$.`, r`This is the ratio of the periods, $T \propto r^{3/2}$.`] }),
  mc("m41", "6.6", "difficult", { stem: r`A satellite of mass $m$ moves in a circular orbit of radius $r$ around a planet of mass $M$. Rockets move it to a larger circular orbit of radius $2r$.`, question: "What is the change in the satellite's total mechanical energy?",
    choices: [r`$+\dfrac{GMm}{4r}$`, r`$+\dfrac{GMm}{2r}$`, r`$-\dfrac{GMm}{4r}$`, r`$+\dfrac{3GMm}{4r}$`],
    why: [r`In a circular orbit, $E = -\dfrac{GMm}{2r}$. So $\Delta E = -\dfrac{GMm}{4r} - \left(-\dfrac{GMm}{2r}\right) = +\dfrac{GMm}{4r}$.`, r`This is the change in the potential energy only, $\Delta U = +\dfrac{GMm}{2r}$. The kinetic energy decreases.`, r`This is the change in the kinetic energy only, which is negative because the satellite moves more slowly.`, r`This subtracts the change in kinetic energy from the change in potential energy instead of adding it.`] }),
  mc("m42", "6.6", "difficult", { stem: r`A probe is launched straight up from the surface of a planet of mass $M$ and radius $R$ with a speed $v = \sqrt{GM/R}$. Air resistance and the planet's rotation are negligible.`, question: "What is the greatest height above the planet's surface that the probe reaches?",
    choices: [r`$R$`, r`$\dfrac{R}{2}$`, r`$2R$`, r`$\dfrac{3R}{2}$`],
    why: [r`Energy conservation: $\tfrac12 mv^2 - \dfrac{GMm}{R} = -\dfrac{GMm}{r_{max}}$. With $v^2 = GM/R$, the left side is $-\dfrac{GMm}{2R}$, so $r_{max} = 2R$ from the center, which is a height of $R$ above the surface.`, r`This assumes that the gravitational field stays at its surface value, $g = GM/R^2$, which gives $h = v^2/2g = R/2$.`, r`This is the greatest distance from the center of the planet, not the height above the surface.`, r`This is the distance from the center found with a constant field, $R + R/2$, reported as a height.`] }),
];

// ---- free response ----
const f = (id, topic, set, part, o) => ({ id: `p6r-${id}`, type: "frq", skill: "u6", topic, set, part, ...o });
const frq = [
  // TBR, 12 points
  f("f1a", "6.5", "p6r-s11", "(a)", { prompt: r`On the dot, which represents the cylinder, draw and label the forces that act on the cylinder as it rolls down the incline. Each force must be drawn as a distinct arrow starting from the dot.`,
    rows: [{ name: "Weight and normal force", earns: r`Draws a downward arrow labeled as the weight (or $mg$ or $F_g$) and an arrow perpendicular to the incline's surface, pointing away from it, labeled as the normal force ($F_N$ or $N$).` },
      { name: "Friction", earns: r`Draws an arrow parallel to the incline, pointing up the slope, labeled as the (static) friction force. No other forces are drawn.` }],
    solution: r`The free-body diagram has three arrows from the dot. The weight $mg$ points straight down. The normal force $F_N$ points perpendicular to the incline, away from the surface. The static friction force $f$ points up the slope, parallel to the surface. The friction arrow is shorter than the component of the weight along the slope, because the cylinder accelerates down the slope.` }),
  f("f1b", "6.5", "p6r-s11", "(b)", { prompt: r`Draw bar charts that show the gravitational potential energy $U_g$, the translational kinetic energy $K_{trans}$, and the rotational kinetic energy $K_{rot}$ of the cylinder at two times: just after it is released, and just before it reaches the bottom of the incline. Take $U_g = 0$ at the height of the cylinder's center at the bottom. Label the bars.`,
    rows: [{ name: "Release", earns: r`Draws a bar chart for the release with a positive $U_g$ bar and $K_{trans}$ and $K_{rot}$ bars of zero height.` },
      { name: "Bottom, shares", earns: r`Draws a bar chart for the bottom with $U_g$ of zero and nonzero $K_{trans}$ and $K_{rot}$ bars, with the $K_{trans}$ bar twice as tall as the $K_{rot}$ bar.` },
      { name: "Conservation", earns: r`Draws the two final kinetic energy bars so that their combined height equals the height of the $U_g$ bar at release.` }],
    solution: r`At release, there is one tall bar for $U_g$ (equal to $mgh$) and no bars for $K_{trans}$ or $K_{rot}$. At the bottom, the $U_g$ bar is zero. The $K_{trans}$ bar is two thirds of the height of the release $U_g$ bar, and the $K_{rot}$ bar is one third of it, so the $K_{trans}$ bar is twice the $K_{rot}$ bar. The two final bars together are as tall as the initial $U_g$ bar. This works because $K_{rot} = \tfrac12\left(\tfrac12 mR^2\right)\left(\tfrac{v}{R}\right)^2 = \tfrac14 mv^2$ and $K_{trans} = \tfrac12 mv^2$.` }),
  f("f1c", "6.5", "p6r-s11", "(c)", { prompt: r`Derive an expression for the speed $v$ of the center of the cylinder just before it reaches the bottom of the incline. Start from a fundamental principle.`,
    rows: [{ name: "Energy conservation", earns: r`Writes $mgh = \tfrac12 mv^2 + \tfrac12 I\omega^2$, or an equivalent statement that the loss of potential energy equals the gain in translational and rotational kinetic energy.` },
      { name: "Rolling condition", earns: r`Uses $\omega = v/R$ and $I = \tfrac12 mR^2$ to write the rotational kinetic energy in terms of $v$, such as $\tfrac14 mv^2$.` },
      { name: "Expression", earns: r`Solves to obtain $v = \sqrt{\dfrac{4gh}{3}}$.` }],
    solution: r`The friction force does no work on a cylinder that rolls without slipping, so mechanical energy is conserved: $mgh = \tfrac12 mv^2 + \tfrac12 I\omega^2$. With $I = \tfrac12 mR^2$ and $\omega = v/R$, the rotational term is $\tfrac12\left(\tfrac12 mR^2\right)\left(\tfrac{v}{R}\right)^2 = \tfrac14 mv^2$. Then $mgh = \tfrac34 mv^2$, so $v = \sqrt{\dfrac{4gh}{3}}$.` }),
  f("f1d", "6.5", "p6r-s11", "(d)(i)", { prompt: r`A block of mass $m$ slides without friction down the same incline from the same starting height $h$. Is the speed of the block at the bottom greater than, less than, or equal to the speed of the cylinder at the bottom? Justify your answer in terms of energy.`,
    rows: [{ name: "Claim", earns: r`States that the block's speed at the bottom is greater than the cylinder's speed.` },
      { name: "Justification", earns: r`States that the block's loss of potential energy $mgh$ becomes only translational kinetic energy, while for the cylinder the same $mgh$ is divided between translational and rotational kinetic energy, so the cylinder has less translational kinetic energy and a lower speed.` }],
    solution: r`The block's speed is greater. Both objects lose the same potential energy, $mgh$. For the block, all of it becomes translational kinetic energy, so $\tfrac12 mv^2 = mgh$ and $v = \sqrt{2gh}$. For the cylinder, part of it becomes rotational kinetic energy, so less is left for the translational motion, and $v = \sqrt{4gh/3}$, which is smaller than $\sqrt{2gh}$.` }),
  f("f1e", "6.5", "p6r-s11", "(d)(ii)", { prompt: r`On one set of axes, sketch the speed of the block and the speed of the cylinder as functions of time from release until each reaches the bottom. Label each line. (Answered on paper.)`,
    rows: [{ name: "Shapes", earns: r`Draws a straight line starting at the origin for each object, labeled, to show a constant acceleration.` },
      { name: "Comparison", earns: r`Draws the block's line with a greater slope than the cylinder's line.` }],
    solution: r`The sketch has speed on the vertical axis and time on the horizontal axis. Each object's graph is a straight line from the origin, because each has a constant acceleration down the incline. The block's acceleration is $g\sin\theta$ and the cylinder's is $\tfrac23 g\sin\theta$, so the block's line is steeper. The block's line ends at a larger speed and, since the distances are the same, at an earlier time.` }),
  // EDA, 10 points
  f("f2a", "6.1", "p6r-s12", "(a)", { prompt: r`The student releases the block from rest from a measured height above the floor and measures its speed $v$ just before it lands. Describe how the student can measure the height $h$ the block falls and the speed $v$ for one release. Name the instrument used for each measurement.`,
    rows: [{ name: "Height", earns: r`States that the height $h$ is measured with a meter stick or ruler, from the block's release position to its position where the speed is measured.` },
      { name: "Speed", earns: r`States that the speed is measured with a photogate near the bottom (flag width divided by the time in the gate), a motion detector, or video analysis of the block's motion.` }],
    solution: r`Set the block at rest at a measured height, with a meter stick next to the string, and read the distance from the release position to the position of the photogate near the floor. Place a photogate there. A flag of known width on the block blocks the beam for a time $\Delta t$, and the speed is the width divided by $\Delta t$.` }),
  f("f2b", "6.1", "p6r-s12", "(b)", { prompt: r`Derive an expression for the rotational inertia $I$ of the disk in terms of $m$, $g$, $h$, $v$, $r$, and fundamental constants. Start from a fundamental principle.`,
    rows: [{ name: "Energy conservation", earns: r`Writes $mgh = \tfrac12 mv^2 + \tfrac12 I\omega^2$, with kinetic energy terms for both the block and the disk.` },
      { name: "Expression", earns: r`Uses $\omega = v/r$ and solves to obtain $I = mr^2\left(\dfrac{2gh}{v^2} - 1\right)$, or an equivalent expression.` }],
    solution: r`Friction is negligible, so energy is conserved for the block, string, and disk: $mgh = \tfrac12 mv^2 + \tfrac12 I\omega^2$. The string does not slip, so $\omega = v/r$. Then $mgh = \tfrac12 mv^2 + \tfrac12 I\dfrac{v^2}{r^2}$, which gives $I = mr^2\left(\dfrac{2gh}{v^2} - 1\right)$.` }),
  f("f2c", "6.1", "p6r-s12", "(c)(i)", { prompt: r`The student repeats the experiment with the same block from five heights. The data are shown in the table. The student wants to find $I$ from a straight-line graph of the data. Indicate two quantities that could be plotted, one on each axis, to produce a straight line, and explain how $I$ could be determined from the line.`,
    rows: [{ name: "Quantities", earns: r`Indicates that $v^2$ is plotted against $h$ (either quantity may be on either axis if the analysis of the slope is consistent).` },
      { name: "Relationship", earns: r`Uses energy conservation to show that $v^2 = \dfrac{2mg}{m + I/r^2}\,h$, a straight line through the origin, so that the slope is $\dfrac{2mg}{m + I/r^2}$ (or its inverse if $h$ is on the vertical axis).` },
      { name: "Use of the slope", earns: r`Explains that $I$ is found by solving for it from the slope: $I = r^2\left(\dfrac{2mg}{\text{slope}} - m\right)$ (or the equivalent for the inverse).` }],
    solution: r`Plot $v^2$ on the vertical axis and $h$ on the horizontal axis. From $mgh = \tfrac12 mv^2 + \tfrac12 I(v/r)^2$, $v^2 = \dfrac{2mg}{m + I/r^2}\,h$, so the graph is a straight line through the origin with slope $\dfrac{2mg}{m + I/r^2}$. The student measures the slope of the best-fit line and solves for $I$: $I = r^2\left(\dfrac{2mg}{\text{slope}} - m\right)$.` }),
  f("f2d", "6.1", "p6r-s12", "(c)(ii)", { prompt: r`On a sheet of graph paper, plot the quantities you indicated in part (c)(i), and draw a best-fit straight line for the data. Label the axes with the quantities and units, and use a scale that makes the points fill more than half of each axis. (Answered on paper.)`,
    rows: [{ name: "Axes and points", earns: r`Labels each axis with the quantity and its units (for example $v^2$ in m²/s² and $h$ in m), uses a linear scale that fills more than half of each axis, and plots the five points correctly.` },
      { name: "Best-fit line", earns: r`Draws a straight best-fit line that passes close to the origin and has about the same number of points above and below it.` }],
    solution: r`The graph has $h$ in m on the horizontal axis from $0$ to $1.0$ and $v^2$ in m²/s² on the vertical axis from $0$ to $3.0$. The points are $(0.20, 0.56)$, $(0.40, 1.08)$, $(0.60, 1.69)$, $(0.80, 2.28)$, and $(1.00, 2.76)$. The best-fit line is straight, passes very near the origin, and has a slope of about $2.8$ m/s².` }),
  f("f2e", "6.1", "p6r-s12", "(c)(iii)", { prompt: r`Use the best-fit line to calculate the rotational inertia $I$ of the disk. Use two points on the line, not data points, to find the slope.`,
    rows: [{ name: "Value of $I$", earns: r`Finds a slope from two points on the line (about $2.8$ m/s², accepted from $2.6$ to $3.0$ m/s²) and obtains $I = r^2\left(\dfrac{2mg}{\text{slope}} - m\right)$ between $2.8 \times 10^{-3}$ and $3.3 \times 10^{-3}$ kg·m², with units.` }],
    solution: r`Take the points $(0, 0)$ and $(1.00, 2.8)$ on the best-fit line. The slope is $2.8$ m/s². Then $I = (0.050)^2\left(\dfrac{2(0.200)(9.8)}{2.8} - 0.200\right) = (0.0025)(1.40 - 0.200) = 3.0 \times 10^{-3}$ kg·m².` }),
];
export default [...mcq, ...frq];
